use std::os::unix::ffi::OsStrExt;

/// glibc atoi(s) == (int)strtol(s, NULL, 10), operating on raw bytes.
fn c_atoi(bytes: &[u8]) -> i32 {
    let mut i = 0usize;
    // C isspace() in the "C" locale
    while i < bytes.len()
        && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
    {
        i += 1;
    }
    let mut neg = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        neg = bytes[i] == b'-';
        i += 1;
    }
    // accumulate as i64 (C `long` on LP64), saturating at i64::MAX / i64::MIN
    let mut acc: i64 = 0;
    let mut overflow = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        let d = (bytes[i] - b'0') as i64;
        if !overflow {
            match acc.checked_mul(10).and_then(|v| v.checked_add(d)) {
                Some(v) => acc = v,
                None => overflow = true,
            }
        }
        i += 1;
    }
    let val: i64 = if overflow {
        if neg { i64::MIN } else { i64::MAX }
    } else if neg {
        // negating a non-overflowed positive acc can never overflow
        -acc
    } else {
        acc
    };
    val as i32
}

fn main() {
    for a in std::env::args_os().skip(1) {
        println!("{}", c_atoi(a.as_bytes()));
    }
}
EOF
